# ---------------------------------------------------------------------------
# (v5) 실측 학습 모형 — 계산
# ---------------------------------------------------------------------------
LAT = 35.23

def _daylength(doy, lat=LAT):
    """CBM 모형 낮 길이(시간)."""
    th = 0.2163108 + 2 * math.atan(0.9671396 * math.tan(0.00860 * (doy - 186)))
    ph = math.asin(0.39795 * math.cos(th))
    v = ((math.sin(0.8333 * math.pi / 180) + math.sin(lat * math.pi / 180) * math.sin(ph))
         / (math.cos(lat * math.pi / 180) * math.cos(ph)))
    return 24 - (24 / math.pi) * math.acos(max(-1.0, min(1.0, v)))

def _photo(date):
    doy = date.timetuple().tm_yday
    return {'daylen': _daylength(doy), 'daylen_d14': _daylength(doy) - _daylength(doy - 14),
            'daylen30': _daylength(doy - 30)}

LON = 128.89

def sun_times(date, lat=LAT, lon=LON):
    """(일출, 일몰) 시각(KST, 시간 단위 실수). 균시차 보정 포함."""
    doy = date.timetuple().tm_yday
    b = math.radians(360.0 / 365.0 * (doy - 81))
    eot = 9.87 * math.sin(2 * b) - 7.53 * math.cos(b) - 1.5 * math.sin(b)   # 분
    noon = 12.0 + (135.0 - lon) * 4.0 / 60.0 - eot / 60.0
    half = _daylength(doy, lat) / 2.0
    return noon - half, noon + half

def _hhmm(h):
    m = int(round(h * 60))
    return '%02d:%02d' % (m // 60, m % 60)

def _dewpoint(t, rh):
    a, b = 17.62, 243.12
    g = math.log(max(rh, 1) / 100.0) + a * t / (b + t)
    return b * g / (a - g)

def _gbm(x):
    s = V5_GBM['base']
    for t in V5_GBM['trees']:
        i = 0
        while t[i][0] != -1:
            f, thr, l, r, ml, _ = t[i]
            v = x[f]
            i = (l if ml else r) if v is None else (l if v <= thr else r)
        s += t[i][5]
    return s

def _lowtemp_gate(ta, ta7):
    te = TA_TODAY_W * ta + (1 - TA_TODAY_W) * ta7
    return _clamp((te - V5_LOWT_T0) / (V5_LOWT_FULL - V5_LOWT_T0))

def features_from_daily(days, date=None):
    """일별 기상 목록(과거→오늘, 최소 8일 권장) → v5 특성.

    days: [{'ta','tmax','tmin','rh','rn','ws','sun'(시간),'td','dusk_t','dusk_ws'(선택)} ...]
          마지막이 오늘. 14~20일 전 강수를 쓰려면 21일 이상 필요.
    """
    date = date or _dt.date.today()
    n = V5_MONTH_NORM[date.month]
    def last(k, n):
        v = [d[k] for d in days[-n:] if d.get(k) is not None]
        return v or [days[-1].get(k) or 0.0]
    mean = lambda k, n: sum(last(k, n)) / len(last(k, n))
    total = lambda k, n: sum(last(k, n))
    t = days[-1]
    f = {'ta': t['ta'], 'tmax': t['tmax'], 'tmin': t['tmin'],
         'ta3': mean('ta', 3), 'ta7': mean('ta', 7), 'ta14': mean('ta', 14),
         'ta21': mean('ta', 21), 'ta30': mean('ta', 30),
         'rh': t['rh'], 'rh7': mean('rh', 7),
         'td': t['td'] if t.get('td') is not None else _dewpoint(t['ta'], t['rh']),
         'rn': t['rn'] or 0.0, 'rn3': total('rn', 3), 'rn7': total('rn', 7),
         'rn14': total('rn', 14), 'rn30': total('rn', 30),
         'rn_lag7_14': sum((d['rn'] or 0.0) for d in days[-14:-7]) if len(days) >= 8 else total('rn', 7),
         'ws': t['ws'], 'ws3': mean('ws', 3), 'sun': t.get('sun') if t.get('sun') is not None else 6.0,
         'gdd14': sum(max(v - V5_LOWT_T0, 0) for v in last('ta', 14)) * (14.0 / len(last('ta', 14))),
         'gdd30': sum(max(v - V5_LOWT_T0, 0) for v in last('ta', 30)) * (30.0 / len(last('ta', 30))),
         'rn_14_20': (sum((d['rn'] or 0.0) for d in days[-21:-14]) if len(days) >= 21
                      else n['rn_14_20']),
         'dusk_t': t['dusk_t'] if t.get('dusk_t') is not None else t['ta'] + (n['dusk_t'] - n['ta']),
         'dusk_ws': (t['dusk_ws'] if t.get('dusk_ws') is not None
                     else t['ws'] * n['dusk_ws'] / max(n['ws'], 0.1))}
    f.update(_photo(date))
    return f

def features_from_inputs(date, temp_c=None, humidity=None, rain_7d_mm=None, ta_7d_avg=None,
                         wind_ms=None, rain_today_mm=None, rain_14_20d_mm=None,
                         dusk_temp_c=None, dusk_wind_ms=None):
    """일부 기상값만 있을 때 — 월평년값에 입력 편차를 전파해 v5 특성을 만든다."""
    n = V5_MONTH_NORM[date.month]
    ta = n['ta'] if temp_c is None else temp_c
    ta7 = (n['ta7'] + (ta - n['ta']) * 0.6) if ta_7d_avg is None else ta_7d_avg
    a = ta7 - n['ta7']                                   # 최근 7일 기온 편차
    rh = n['rh'] if humidity is None else humidity
    rn7 = n['rn7'] if rain_7d_mm is None else rain_7d_mm
    rn = (n['rn'] if temp_c is None else 0.0) if rain_today_mm is None else rain_today_mm
    ws = n['ws'] if wind_ms is None else wind_ms
    rn14 = rn7 + max(n['rn14'] - n['rn7'], 0)
    f = {'ta': ta, 'tmax': ta + (n['tmax'] - n['ta']), 'tmin': ta + (n['tmin'] - n['ta']),
         'ta3': (ta + ta7) / 2, 'ta7': ta7, 'ta14': n['ta14'] + 0.8 * a,
         'ta21': n['ta21'] + 0.7 * a, 'ta30': n['ta30'] + 0.6 * a,
         'rh': rh, 'rh7': rh if humidity is not None else n['rh7'],
         'td': _dewpoint(ta, rh) if humidity is not None else n['td'] + (ta - n['ta']),
         'rn': rn, 'rn3': min(rn7, rn + (rn7 - rn) * 2 / 6.0), 'rn7': rn7, 'rn14': rn14,
         'rn30': rn14 + max(n['rn30'] - n['rn14'], 0), 'rn_lag7_14': n['rn_lag7_14'],
         'ws': ws, 'ws3': ws, 'sun': n['sun'],
         'gdd14': max(0.0, n['gdd14'] + 14 * 0.8 * a), 'gdd30': max(0.0, n['gdd30'] + 30 * 0.6 * a),
         'rn_14_20': n['rn_14_20'] if rain_14_20d_mm is None else rain_14_20d_mm,
         'dusk_t': (ta + (n['dusk_t'] - n['ta'])) if dusk_temp_c is None else dusk_temp_c,
         'dusk_ws': (ws * n['dusk_ws'] / max(n['ws'], 0.1)) if dusk_wind_ms is None else dusk_wind_ms}
    f.update(_photo(date))
    return f

def _temporal(feats):
    """(시간효과 log, 저온차단계수)"""
    x = [feats.get(k, 1.0 if k == 'moscom' else None) for k in V5_FEATS]
    return _gbm(x), _lowtemp_gate(feats['ta'], feats['ta7'])

def _count_to_index(cnt):
    return _clamp(math.log1p(max(cnt, 0.0)) / math.log1p(V5_CAP)) * 100

def _expected_count(district, tctx, z=0.0):
    g, gate = tctx
    return math.expm1(V5_OFFSET[district] + g + z * V5_RESID_SD) * gate

def expected_count(district, feats):
    """구역의 예상 채집수(마리/트랩·일, 공원형 유인트랩 기준)."""
    return _expected_count(district, _temporal(feats))

# ---------------------------------------------------------------------------
# (1) v4 기상 활동지수 — 설명용 구성요소(components) 산출에만 사용
# ---------------------------------------------------------------------------
def _briere(T):
    """Brière 곡선. 발육영점 T0 이하 / 치사상한 Tm 이상에서 0."""
    if T <= BRIERE['T0'] or T >= BRIERE['Tm']:
        return 0.0
    v = (BRIERE['a'] * T * (T - BRIERE['T0'])
         * ((BRIERE['Tm'] - T) ** (1.0 / BRIERE['m'])))
    return _clamp(v / BRIERE_NORM)

def _temp_suit(temp_c, ta_7d_avg=None):
    """유효기온(당일 29% + 7일평균 71%) 기반 기온 적합도."""
    t7 = temp_c if ta_7d_avg is None else ta_7d_avg
    te = TA_TODAY_W * temp_c + (1 - TA_TODAY_W) * t7
    v = _briere(te)
    if   te < 11: s = '발육영점 이하 — 모기 활동 거의 정지'
    elif te < 16: s = '저온 — 활동 저조, 월동개체 위주'
    elif te < 22: s = '상승기 — 발생 시작'
    elif te < 26: s = '양호 — 번식·흡혈 활발'
    elif te <= 32: s = '최적 — 발생 정점 구간'
    elif te <= 36: s = '고온 — 활동 다소 둔화'
    else: s = '극한 폭염 — 활동 급감'
    return round(v, 3), s, round(te, 1)

def _hum_suit(H):
    v = _clamp(HUM_BASE + HUM_SLOPE * (H - 40) / 50.0, 0.30, 1.05)
    if   H < 50: s = '건조 — 성충 수명 단축'
    elif H < 70: s = '보통'
    else: s = '다습 — 성충 생존에 유리'
    return round(v, 3), s

def _rain_suit(rain_7d_mm, rain_today_mm=0.0):
    """최근 7일 누적강수는 산란처를 늘리고(+), 당일 폭우는 유충을 씻어낸다(-)."""
    v = (1.0 + RAIN_W * math.tanh(rain_7d_mm / 40.0)
         - 0.9 * RAIN_W * math.tanh(rain_today_mm / 25.0))
    v = _clamp(v, 0.85, 1.15)
    if   rain_today_mm >= 30: s = '당일 폭우 — 유충 유실로 일시 감소'
    elif rain_7d_mm >= 40: s = '최근 강수 많음 — 산란처 확대'
    elif rain_7d_mm >= 10: s = '적당한 강수 — 고인물 유지'
    else: s = '건조 지속 — 기존 정체수 위주'
    return round(v, 3), s

def _wind_suit(ws):
    v = _clamp(1.0 - WIND_W * (ws - 1.5) / 3.0, 0.55, 1.15)
    if   ws >= 4.0: s = '강풍 — 비행·흡혈 억제'
    elif ws >= 2.5: s = '바람 다소 강함 — 활동 일부 억제'
    else: s = '약풍 — 활동에 지장 없음'
    return round(v, 3), s

def weather_activity(temp_c, humidity, rain_7d_mm, wind_ms=1.8, ta_7d_avg=None,
                     rain_today_mm=0.0):
    """0~1 기상 활동지수. v3의 weather_activity(t,h,r) 호출도 그대로 동작한다."""
    t = _temp_suit(temp_c, ta_7d_avg)[0]
    h = _hum_suit(humidity)[0]
    r = _rain_suit(rain_7d_mm, rain_today_mm)[0]
    w = _wind_suit(wind_ms)[0]
    return _clamp(t * h * r * w)

# ---------------------------------------------------------------------------
# (2) 실시간 기상 — Open-Meteo (무료/키 불필요, 표준 라이브러리만)
#     v5는 최근 31일 일별 기상 + 오늘 일몰 후 시간별 기상이 필요하다.
# ---------------------------------------------------------------------------
_DAILY = ('temperature_2m_mean,temperature_2m_max,temperature_2m_min,'
          'relative_humidity_2m_mean,precipitation_sum,wind_speed_10m_mean,'
          'sunshine_duration,dew_point_2m_mean,sunset')

def _dusk_by_day(loc):
    """날짜별 일몰 후 4시간 평균 기온·풍속."""
    h, d = loc.get('hourly') or {}, loc['daily']
    sunset = {day: s for day, s in zip(d['time'], d.get('sunset') or [])}
    acc = {}
    for i, ts in enumerate(h.get('time', [])):
        day = ts[:10]; ss = sunset.get(day)
        if not ss:
            continue
        rel = (int(ts[11:13]) * 60 + int(ts[14:16]) - int(ss[11:13]) * 60 - int(ss[14:16])) / 60.0
        if 0 <= rel < 4:
            t, w = h['temperature_2m'][i], h['wind_speed_10m'][i]
            if t is not None and w is not None:
                a = acc.setdefault(day, [0.0, 0.0, 0]); a[0] += t; a[1] += w; a[2] += 1
    return {k: (v[0] / v[2], v[1] / v[2]) for k, v in acc.items() if v[2] >= 2}

def _parse_meteo(loc):
    d = loc['daily']
    dusk = _dusk_by_day(loc)
    days = []
    for i, day in enumerate(d['time']):
        ta = d['temperature_2m_mean'][i]
        if ta is None:
            continue
        sun = d['sunshine_duration'][i]
        days.append({'date': day, 'ta': ta, 'tmax': d['temperature_2m_max'][i],
                     'tmin': d['temperature_2m_min'][i],
                     'rh': d['relative_humidity_2m_mean'][i],
                     'rn': d['precipitation_sum'][i] or 0.0,
                     'ws': d['wind_speed_10m_mean'][i],
                     'sun': (sun / 3600.0) if sun is not None else None,
                     'td': d['dew_point_2m_mean'][i],
                     'dusk_t': dusk.get(day, (None, None))[0],
                     'dusk_ws': dusk.get(day, (None, None))[1],
                     'sunset': (d.get('sunset') or [None] * len(d['time']))[i]})
    today = _dt.date.fromisoformat(days[-1]['date'])
    feats = features_from_daily(days, today)
    t = days[-1]
    return {'temp_c': round(t['ta'], 1), 'humidity': round(t['rh']),
            'ta_7d_avg': round(feats['ta7'], 1), 'rain_7d_mm': round(feats['rn7'], 1),
            'rain_today_mm': round(t['rn'], 1), 'wind_ms': round(t['ws'], 1),
            'date': days[-1]['date'], 'source': 'open-meteo', 'v5_features': feats,
            'sunset': (t.get('sunset') or '')[11:16] or None}

def _meteo_url(lats, lons):
    import urllib.parse
    return 'https://api.open-meteo.com/v1/forecast?' + urllib.parse.urlencode({
        'latitude': lats, 'longitude': lons, 'daily': _DAILY,
        'hourly': 'temperature_2m,wind_speed_10m',
        'past_days': 31, 'forecast_days': 1, 'timezone': 'Asia/Seoul',
        'wind_speed_unit': 'ms',
    })

def fetch_weather(district=None, lat=None, lon=None, timeout=10):
    """오늘 기상 + 최근 31일 기반 v5 특성. 실패 시 None."""
    import urllib.request
    if lat is None or lon is None:
        lat, lon = COORDS.get(district, KIMHAE_CENTER)
    try:
        with urllib.request.urlopen(_meteo_url(lat, lon), timeout=timeout) as resp:
            data = json.loads(resp.read().decode('utf-8'))
        out = _parse_meteo(data)
        out['lat'], out['lon'] = lat, lon
        return out
    except Exception:
        return None

def fetch_weather_bulk(districts, timeout=15):
    """여러 구역 날씨를 한 번의 호출로. 실패 시 None."""
    import urllib.request
    lats, lons = [], []
    for d in districts:
        la, lo = COORDS.get(d, KIMHAE_CENTER)
        lats.append(str(la)); lons.append(str(lo))
    try:
        with urllib.request.urlopen(_meteo_url(','.join(lats), ','.join(lons)),
                                    timeout=timeout) as resp:
            data = json.loads(resp.read().decode('utf-8'))
        if isinstance(data, dict):
            data = [data]
        return {d: _parse_meteo(loc) for d, loc in zip(districts, data)}
    except Exception:
        return None

# ---------------------------------------------------------------------------
# (3) 지역 위험 — 설명용 (발생원 기여도·등급·조언)
# ---------------------------------------------------------------------------
def grade(index):
    # 홈 화면과 같은 5단계 (반올림한 정수로 판정)
    n = round(index)
    if n <= 20: return (1, '매우 낮음', '#5FD08A')
    if n <= 40: return (2, '낮음', '#B5D65A')
    if n <= 60: return (3, '보통', '#F2C94C')
    if n <= 80: return (4, '높음', '#F08A3E')
    return (5, '매우 높음', '#E5484D')

def _source_breakdown(rec):
    """발생원별 위험 기여도 — '개수'가 아니라 '밀도(개/㎢)' 기준."""
    contrib = {}
    area = rec['area_km2']
    for k, cnt in rec['sources'].items():
        den = cnt / area
        mx = _MAX_SRC_DEN.get(k, 0.0)
        contrib[k] = (den / mx if mx > 0 else 0.0) * RISK_W.get(k, 1.0)
    tot = sum(contrib.values()) or 1.0
    rows = []
    for k in sorted(contrib, key=lambda x: -contrib[x]):
        if rec['sources'].get(k, 0) > 0:
            rows.append({'source': SRC_KOR[k], 'count': rec['sources'][k],
                         'per_km2': round(rec['sources'][k] / area, 1),
                         'risk_contribution_pct': round(100 * contrib[k] / tot, 1)})
    return rows

def _citizen_advice(level, top_source_name):
    base = {
        1: ['특별한 조치가 필요 없습니다.'],
        2: ['야간 외출 시 가벼운 기피제를 사용하세요.',
            '집 주변 화분받침·빈 용기의 고인물을 비우세요.'],
        3: ['방충망·기피제를 사용하고 해질녘 야외 활동을 줄이세요.',
            '집 주변 정화조·하수구 뚜껑 주변을 점검하세요.',
            '고인물 용기를 뒤집어 두세요.'],
        4: ['해질녘·새벽 야외활동을 줄이고 긴팔·긴바지를 착용하세요.',
            'DEET 10~20% 또는 이카리딘 기피제를 사용하세요.',
            '집 안팎 고인물을 즉시 제거하세요.'],
        5: ['야외활동을 자제하고 긴팔·긴바지를 착용하세요.',
            '농도 높은 기피제(DEET 20%+·이카리딘)를 사용하세요.',
            '집 안팎 모든 고인물을 즉시 제거하세요.'],
    }[level]
    tip = {
        '정화조(청소대상)': '하수구·정화조 환기구 주변에 모기가 모입니다.',
        '개인하수처리시설': '오수처리시설 주변 정체수가 주요 산란처입니다.',
        '개인오수처리시설': '오수처리시설 주변 정체수가 주요 산란처입니다.',
        '타이어가게': '야적된 폐타이어에 빗물이 고이지 않게 관리가 필요합니다.',
        '폐타이어적치': '적치된 타이어의 빗물이 대표적 산란처입니다.',
        '수경시설': '분수·바닥분수 등 정체수 주변을 피하세요.',
        '축산농가': '축사 주변 분뇨·물웅덩이에서 모기가 다량 발생합니다.',
        '저수지': '저수지 가장자리 정체수 구역을 주의하세요.',
        '공중화장실': '공중화장실 주변 정화조에서 유충이 생길 수 있습니다.',
        '도시공원': '공원 내 인공연못·배수로 정체수를 주의하세요.',
        '고물상': '야적 폐기물에 고인 빗물이 산란처가 됩니다.',
    }.get(top_source_name)
    return base + ([tip] if tip and level >= 2 else [])

def _authority_advice(rec, level, rank, total, larva_rate):
    a = []
    if level >= 3:
        a.append('취약구역 방역 주기를 단축하고 유문등·포충기 가동을 강화하세요.')
    if rank <= max(3, total // 5):
        a.append('본 구역은 밀도위험 상위(%d/%d)입니다. 정화조·하수구 유충구제'
                 '(라바사이드)를 선제 시행하세요.' % (rank, total))
    if rec['data_gap']:
        a.append('민원·현장조사 자료가 미제공된 결측 구역입니다 — 인구·발생원 밀도로만 '
                 '추정했으므로 우선 현장 조사로 데이터를 확보하세요.')
    elif rec['complaints_2025'] == 0 and level >= 3:
        a.append('발생원 밀도는 높으나 민원 기록이 없는 사각지대입니다 — 선제 점검을 권장합니다.')
    if larva_rate is not None and larva_rate >= 0.6:
        a.append('유충 실태조사 검출률이 %d%%로 높습니다 — 발생원 시설 자체의 관리상태가 '
                 '불량합니다(모기지수와 별개로 시설 개선 대상).' % round(100 * larva_rate))
    if not a:
        a.append('정기 방역 주기를 유지하세요.')
    return a

def _confidence(weather_observed, rec):
    """불확실성 라벨: 기상 실측 여부 + 민원 결측 + 인구 추정 여부 (설명용)."""
    wu = 0.06 if weather_observed else 0.20
    gu = 0.22 if rec['data_gap'] else 0.08
    pu = 0.10 if rec['pop_estimated'] else 0.0
    u = (wu ** 2 + gu ** 2 + pu ** 2) ** 0.5
    label = '높음' if u < 0.13 else ('보통' if u < 0.21 else '낮음')
    return u, label

# ---------------------------------------------------------------------------
# (4) 메인 API
# ---------------------------------------------------------------------------
def _index_of(district, tctx):
    """(지수, 구역 밀도위험) — tctx = _temporal(feats)."""
    rec = DISTRICTS[district]
    geo = W_BREED * rec['breed_norm'] + W_POPD * rec['popd_norm']
    return round(_count_to_index(_expected_count(district, tctx)), 1), geo

def _resolve_date(date, month):
    if date is not None:
        return _dt.date.fromisoformat(date) if isinstance(date, str) else date
    if month is not None:
        return _dt.date(_dt.date.today().year, int(month), 15)
    return _dt.date.today()

def mosquito_index(district, month=None, temp_c=None, humidity=None, rain_3d_mm=None,
                   live_weather=False, wind_ms=None, ta_7d_avg=None, rain_7d_mm=None,
                   rain_today_mm=None, date=None, rain_14_20d_mm=None,
                   dusk_temp_c=None, dusk_wind_ms=None, _wx=None):
    """구역의 모기지수와 부가정보를 반환.

    날짜 결정: date > month(해당 월 15일) > 오늘. v5는 낮 길이가 핵심 변수라 날짜가 필요하다.
    rain_14_20d_mm(14~20일 전 강수 합), dusk_temp_c/dusk_wind_ms(일몰 후 4시간 평균)은
    선택 입력이며, 없으면 월평년값과 입력 기온·풍속으로 추정한다.
    rain_3d_mm 은 v3 호환용 별칭이며, 값이 주어지면 rain_7d_mm 으로 취급한다.
    """
    if district not in DISTRICTS:
        raise KeyError('unknown district: ' + str(district))
    if rain_7d_mm is None:
        rain_7d_mm = rain_3d_mm
    day = _resolve_date(date, month)

    caller_provided = temp_c is not None
    weather_observed = False
    weather_src = 'manual' if caller_provided else 'climatology'
    feats = None

    if _wx is None and live_weather and temp_c is None and humidity is None and rain_7d_mm is None:
        _wx = fetch_weather(district)
    if _wx is not None:
        temp_c, humidity = _wx['temp_c'], _wx['humidity']
        rain_7d_mm, ta_7d_avg = _wx['rain_7d_mm'], _wx['ta_7d_avg']
        wind_ms, rain_today_mm = _wx['wind_ms'], _wx['rain_today_mm']
        feats = _wx.get('v5_features')
        if _wx.get('date'):
            day = _dt.date.fromisoformat(_wx['date'])
        weather_observed = True
        weather_src = _wx.get('source', 'open-meteo')
    if feats is None:
        feats = features_from_inputs(day, temp_c, humidity, rain_7d_mm, ta_7d_avg,
                                     wind_ms, rain_today_mm, rain_14_20d_mm,
                                     dusk_temp_c, dusk_wind_ms)
    month = day.month
    temp_c, ta_7d_avg = round(feats['ta'], 1), round(feats['ta7'], 1)
    humidity, rain_7d_mm = round(feats['rh'], 1), round(feats['rn7'], 1)
    wind_ms, rain_today_mm = round(feats['ws'], 1), round(feats['rn'], 1)

    # 설명용 구성요소 (v4 곡선) — 지수 계산에는 쓰지 않음
    tv, ts, te = _temp_suit(temp_c, ta_7d_avg)
    hv, hs = _hum_suit(humidity)
    rv, rs = _rain_suit(rain_7d_mm, rain_today_mm)
    wv, ws = _wind_suit(wind_ms)

    tctx = _temporal(feats)
    g, gate = tctx
    rec = DISTRICTS[district]
    index, geo = _index_of(district, tctx)
    lv, nm, col = grade(index)
    cnt = _expected_count(district, tctx)
    cnt_lo = _expected_count(district, tctx, -V5_Z50)
    cnt_hi = _expected_count(district, tctx, V5_Z50)
    band_low = round(_count_to_index(cnt_lo), 1)
    band_high = round(_count_to_index(cnt_hi), 1)
    # 도시 평균 구역 기준 활동지수(0~1): 시간효과만의 크기
    city_off = sum(V5_OFFSET.values()) / len(V5_OFFSET)
    act = _clamp(math.log1p(max(math.expm1(city_off + g) * gate, 0)) / math.log1p(V5_CAP))
    if gate < 1:
        ts = ts + ' (저온 차단계수 %.2f 적용)' % gate

    u, conf_label = _confidence(weather_observed or caller_provided, rec)

    breakdown = _source_breakdown(rec)
    top_name = breakdown[0]['source'] if breakdown else None
    surveyed = rec.get('larva_surveyed', 0)
    larva_rate = (rec.get('larva_positive', 0) / surveyed) if surveyed >= 10 else None

    all_idx = sorted(((d, _index_of(d, tctx)[0]) for d in DISTRICTS), key=lambda x: -x[1])
    ranked = [d for d, _ in all_idx]
    rank = ranked.index(district) + 1
    total = len(all_idx)
    city_avg = round(sum(v for _, v in all_idx) / total, 1)
    top_district, top_val = all_idx[0]
    pri_rank = sorted(DISTRICTS, key=lambda d: -DISTRICTS[d]['control_priority']).index(district) + 1

    area_type = ('농촌형(축산·정화조 산재)' if district.endswith(('읍', '면'))
                 else '도심형(생활하수·수경시설·공원)')
    dl = feats['daylen']
    season_txt = ('낮이 짧아져 모기가 월동 준비에 들어가는 시기' if feats['daylen_d14'] < 0 and dl < 13.0
                  else ('낮이 길어지며 개체수가 늘어나는 시기' if feats['daylen_d14'] > 0 else '번식 성수기'))
    act_txt = ('모기 활동이 왕성' if act >= 0.6
               else ('모기 활동이 제한적' if act < 0.3 else '보통 수준의 활동'))
    sunrise_h, sunset_h = sun_times(day)
    sunset_txt = (_wx or {}).get('sunset') or _hhmm(sunset_h)
    act_end = _hhmm(int(sunset_txt[:2]) + int(sunset_txt[3:5]) / 60.0 + 3)
    active_hours = (('일몰(%s) 직후~%s, 일출(%s) 전 2시간에 가장 활발'
                     % (sunset_txt, act_end, _hhmm(sunrise_h))) if lv >= 2 else '활동 미약')
    dk_t, dk_w, r1420 = feats['dusk_t'], feats['dusk_ws'], feats['rn_14_20']
    dusk_txt = ('일몰 후 %.1f℃·바람 %.1fm/s — %s' % (dk_t, dk_w,
                '바람이 강해 저녁 활동 억제' if dk_w >= 3.0 else
                ('저녁 기온이 낮아 활동 둔화' if dk_t < 15 else '저녁 흡혈 활동에 적합')))
    lag_txt = ('14~20일 전 강수 %.0fmm — %s' % (r1420,
               '그때 생긴 물웅덩이에서 지금 성충이 나오는 시기' if r1420 >= 30 else
               ('보통' if r1420 >= 10 else '2~3주 전 건조 — 신규 발생 적음')))
    repellent = {1: '불필요', 2: '가벼운 기피제(시트로넬라 등)',
                 3: '기피제(이카리딘·DEET 10%) 권장',
                 4: 'DEET 10~20% 또는 이카리딘 + 긴팔 권장',
                 5: 'DEET 20%+ 또는 이카리딘 고농도, 노출 최소화'}[lv]

    return {
        'district': district,
        'model_version': 'v5.2',
        'date': day.isoformat(),
        'mosquito_index': index,
        'index_range': {'low': band_low, 'high': band_high, 'interval': '50% 예측구간'},
        'expected_trap_count': {
            'value': round(cnt, 1), 'low': round(cnt_lo, 1), 'high': round(cnt_hi, 1),
            'unit': '마리/트랩·일 (공원형 유인트랩 기준)'},
        'level': lv, 'grade': nm, 'color': col,
        'confidence': {
            'level': conf_label,
            'uncertainty_pct': round(100 * u, 1),
            'reasons': {
                'weather': ('실측(Open-Meteo)' if weather_observed
                            else ('직접입력' if caller_provided else '월평년값')),
                'population': '100m 격자 추정' if rec['pop_estimated'] else '주민등록',
                'complaint_data': '미제공(결측)' if rec['data_gap'] else '보유',
            },
            'note': ('⚠ 민원·현장조사 미제공 구역 — 지역 수준은 주변 발생원·인구 특성으로 '
                     '추정한 값입니다(민원 0건을 안전으로 해석하지 마세요).' if rec['data_gap'] else None),
        },
        'summary': (district + '의 모기지수는 ' + str(index) + '점(' + str(lv) + '단계 '
                    + nm + ', ' + str(band_low) + '~' + str(band_high) + '점)입니다. '
                    + '공원 트랩 기준 하루 약 ' + str(int(round(cnt))) + '마리가 예상되며, '
                    + season_txt + '로 ' + act_txt + '합니다. 시내 ' + str(rank) + '/'
                    + str(total) + '위.'
                    + (' ※ 민원 자료 미제공 구역으로 추정치입니다.' if rec['data_gap'] else '')),
        'weather': {
            'input': {'temp_c': temp_c, 'ta_7d_avg': ta_7d_avg, 'humidity': humidity,
                      'rain_7d_mm': rain_7d_mm, 'rain_today_mm': rain_today_mm,
                      'wind_ms': wind_ms, 'month': month},
            'source': weather_src,
            'observed': weather_observed,
            'effective_temp_c': te,
            'activity_index': round(act, 3),
            'daylength_h': round(dl, 2),
            'season_phase': season_txt,
            'low_temp_gate': round(gate, 3),
            'sunset': sunset_txt,
            'dusk': {'temp_c': round(dk_t, 1), 'wind_ms': round(dk_w, 1)},
            'rain_14_20d_mm': round(r1420, 1),
            'components': {
                'temperature': {'score': tv, 'status': ts, 'effective_temp_c': te},
                'humidity':    {'score': hv, 'status': hs},
                'rainfall':    {'score': rv, 'status': rs},
                'wind':        {'score': wv, 'status': ws},
                'rain_lag':    {'score': None, 'status': lag_txt},
                'dusk':        {'score': None, 'status': dusk_txt},
                'daylength':   {'score': round(dl / 14.5, 3),
                                'status': '낮 길이 %.1f시간 — %s' % (dl, season_txt)},
            },
            'comment': ('기온 ' + str(temp_c) + '℃(7일평균 ' + str(ta_7d_avg) + '℃, 30일평균 '
                        + str(round(feats['ta30'], 1)) + '℃), 습도 ' + str(humidity)
                        + '%, 최근7일 강수 ' + str(rain_7d_mm) + 'mm, 풍속 ' + str(wind_ms)
                        + 'm/s, 낮 길이 ' + str(round(dl, 1)) + '시간 → 활동지수 '
                        + str(round(act, 2))),
        },
        'area': {
            'area_km2': rec['area_km2'],
            'population': rec['population'],
            'pop_density': rec['pop_density'],
            'pop_density_norm': rec['popd_norm'],
            'estimated': rec['pop_estimated'],
            'water_pct': rec['water_pct'],
            'park_m2_per_km2': rec['park_m2_per_km2'],
        },
        'source_risk': {
            'density_risk': round(geo, 3),
            'trap_level_log': V5_OFFSET[district],
            'breed_density_per_km2': rec['breed_density'],
            'breed_density_norm': rec['breed_norm'],
            'pop_density_norm': rec['popd_norm'],
            'control_priority': rec['control_priority'],
            'control_priority_rank': pri_rank,
            'area_type': area_type,
            'top_sources': breakdown[:5],
            'total_facilities': sum(rec['sources'].values()),
            'comment': (('주요 발생원은 ' + top_name + '이며, 이 구역은 ' + area_type
                         + '입니다. 발생원 ' + format(sum(rec['sources'].values()), ',')
                         + '개소 / ' + str(rec['area_km2']) + '㎢.')
                        if top_name else '등록 발생원 없음'),
        },
        'larva_survey': {
            'surveyed': surveyed,
            'positive': rec.get('larva_positive', 0),
            'detection_rate': round(larva_rate, 3) if larva_rate is not None else None,
            'used_in_index': False,
            'note': ('발생원 시설의 관리상태 지표입니다. 민원밀도와 음의 상관(-0.715)이어서 '
                     '모기지수 산출에는 쓰지 않고, 시설 개선 우선순위 참고용으로만 제공합니다.'),
        },
        'ranking': {
            'rank': rank, 'total_districts': total,
            'percentile': round(100 * (total - rank + 1) / total, 1),
            'city_avg_index': city_avg,
            'vs_city_avg': round(index - city_avg, 1),
            'highest_district': {'name': top_district, 'index': top_val},
        },
        'complaints_2025': rec['complaints_2025'],
        'advice': {
            'citizen': _citizen_advice(lv, top_name),
            'authority': _authority_advice(rec, lv, rank, total, larva_rate),
        },
        'active_hours': active_hours,
        'recommended_repellent': repellent,
    }

def all_indices(month=None, live_weather=False, date=None, **wx):
    if live_weather and not wx:
        bulk = fetch_weather_bulk(list(DISTRICTS))
        if bulk is not None:
            res = [mosquito_index(d, month=month, date=date, _wx=bulk.get(d)) for d in DISTRICTS]
            return sorted(res, key=lambda x: -x['mosquito_index'])
    res = [mosquito_index(d, month=month, date=date, **wx) for d in DISTRICTS]
    return sorted(res, key=lambda x: -x['mosquito_index'])

def control_priority_ranking():
    """방제 우선순위(총부담 = 밀도위험 × 인구). 민원 건수와 스피어만 +0.765."""
    rows = [{'district': d, 'control_priority': DISTRICTS[d]['control_priority'],
             'density_risk': round(W_BREED * DISTRICTS[d]['breed_norm']
                                   + W_POPD * DISTRICTS[d]['popd_norm'], 3),
             'population': DISTRICTS[d]['population'],
             'area_km2': DISTRICTS[d]['area_km2'],
             'complaints_2025': DISTRICTS[d]['complaints_2025'],
             'data_gap': DISTRICTS[d]['data_gap']}
            for d in DISTRICTS]
    rows.sort(key=lambda r: -r['control_priority'])
    for i, r in enumerate(rows, 1):
        r['rank'] = i
    return rows

def list_districts():
    return list(DISTRICTS.keys())

if __name__ == '__main__':
    print(json.dumps(mosquito_index('활천동', temp_c=26, humidity=80, rain_7d_mm=50,
                                    ta_7d_avg=25.5, wind_ms=1.6, date='2026-07-01'),
                     ensure_ascii=False, indent=2))
    for m in (5, 6, 7, 8, 9, 10):
        print('\n[%d월 평년 전 구역 모기지수]' % m)
        for r in all_indices(month=m):
            print('  %-8s %5.1f  (%s)  예상 %6.1f마리'
                  % (r['district'], r['mosquito_index'], r['grade'],
                     r['expected_trap_count']['value']))
